START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261111114930_AddCampaignsAndHeroBanners') THEN
    CREATE TABLE campaigns (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "TitleAr" character varying(150) NOT NULL,
        "TitleEn" character varying(150) NOT NULL,
        "SubtitleAr" character varying(300),
        "SubtitleEn" character varying(300),
        "CtaAr" character varying(80),
        "CtaEn" character varying(80),
        "BadgeAr" character varying(50),
        "BadgeEn" character varying(50),
        "ImageUrlMobile" character varying(1000) NOT NULL,
        "ImageUrlDesktop" character varying(1000),
        "TargetUrl" character varying(1000),
        "Priority" integer NOT NULL DEFAULT 0,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "StartDate" timestamp with time zone,
        "EndDate" timestamp with time zone,
        "TextAlignment" character varying(20) NOT NULL DEFAULT 'center',
        "OverlayOpacity" numeric(3,2) NOT NULL DEFAULT 0.35,
        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
        "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
        CONSTRAINT "PK_campaigns" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

