DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261111114930_AddCampaignsAndHeroBanners') THEN
    CREATE INDEX "IX_campaigns_IsActive" ON campaigns ("IsActive");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261111114930_AddCampaignsAndHeroBanners') THEN
    CREATE INDEX "IX_campaigns_IsActive_Priority" ON campaigns ("IsActive", "Priority");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261111114930_AddCampaignsAndHeroBanners') THEN
    CREATE INDEX "IX_campaigns_Priority" ON campaigns ("Priority");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261111114930_AddCampaignsAndHeroBanners') THEN
    PERFORM setval(
        pg_get_serial_sequence('campaigns', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM campaigns) + 1,
            nextval(pg_get_serial_sequence('campaigns', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
